?'font-bold text-slate-900':''" x-text="r['supplement'] || '—'"></td><td class="px-4 py-4" :class="f.key==='animal_id'?'font-bold text-slate-900':''" x-text="r['treatment'] || '—'"></td><td class="max-w-sm px-4 py-4 whitespace-pre-line" x-text="r['services'] || '—'"></td><td class="px-4 py-4" :class="f.key==='animal_id'?'font-bold text-slate-900':''" x-text="r['body_condition'] || '—'"></td><td class="px-4 py-4" :class="f.key==='animal_id'?'font-bold text-slate-900':''" x-text="r['temperature'] || '—'"></td><td class="px-4 py-4" :class="f.key==='animal_id'?'font-bold text-slate-900':''" x-text="r['remarks'] || '—'"></td><td class="whitespace-nowrap px-4 py-4"><button type="button" @click="view(r)" class="mr-1 rounded-lg border border-slate-200 px-3 py-2 hover:bg-blue-50" title="View details"><i class="fa-solid fa-eye"></i></button><button type="button" @click="remove(r.id)" class="rounded-lg px-3 py-2 text-red-600 hover:bg-red-50" title="Delete record"><i class="fa-solid fa-trash"></i></button></td></tr></template><tr x-show="filteredRecords.length===0"><td colspan="16" class="px-5 py-12 text-center text-slate-500"><i class="fa-solid fa-folder-open mb-2 block text-2xl text-slate-300"></i>No records found. Change your filters or add records.</td></tr></tbody></table></div>
