ate-100 text-xs uppercase tracking-wider text-slate-600"><tr><th class="p-3">Animal ID *</th><th class="p-3">Farmer</th><th class="p-3">Province</th><th class="p-3">Cooperative / Association</th><th class="p-3">Monitoring Date *</th><th class="p-3">Health Status *</th><th class="p-3">Observed Condition</th><th class="p-3">Feed</th><th class="p-3">Supplement</th><th class="p-3">Treatment</th><th class="p-3">Body Condition</th><th class="p-3">Temperature (°C)</th><th class="p-3">Remarks</th><th class="p-3">Action</th></tr></thead><tbody class="divide-y divide-slate-100"><template x-for="(r,i) in bulkRows" :key="r._key"><tr class="align-top"><template x-for="f in fieldMeta" :key="f.key"><td class="min-w-40 p-2"><template x-if="['province','health','body','session','stage','result','exit','exitstatus'].includes(f.type)"><select x-model="r[f.key]" class="form-input"><option value="">Select <span x-text="f.label"></span></option><template x-for="v in optionValues(f.type)" :key="v"><option :value="v" x-text="v"></option></template></select></template><template x-if="!['province','health','body','session','stage','result','exit','exitstatus'].includes(f.type)"><input :type="f.type==='date'?'date':f.type==='number'?'number':'text'" x-model="r[f.key]" class="form-input" :placeholder="f.label" :required="f.required"></template></td></template><td class="p-2 text-center"><button @click="removeRow(i)" type="button" class="rounded-lg px-3 py-2 text-red-600 hover:bg-red-50" title="Remove row"><i class="fa-solid fa-trash"></i></button></td></tr></template><tr x-show="bulkRows.length===0"><td colspan="14" class="px-4 py-10 text-center text-slate-500">No rows. Click Add Row to begin.</td></tr></tbody></table></div><div class="mt-4 flex flex-col gap-3 rounded-xl bg-slate-50 p-4 sm:flex-row sm:items-center sm:justify-between"><div><p class="text-sm font-semibold text-slate-800">Batch total: <span x-text="bulkRows.length"></span> row(s)</p><p class="mt-1 text-xs text-slate-500">Fields marked with * are required.</p></div><div class="flex justify-end gap-2"><button @click="showBulk=false" type="button" class="rounded-lg border border-slate-300 bg-white px-5 py-2.5 text-sm font-semibold hover:bg-slate-100">Cancel</button><button @click="saveBulk()" type="button" class="rounded-lg bg-[#0b1f3a] px-5 py-2.5 text-sm font-semibold text-white hover:bg-[#122b4d]"><i class="fa-solid fa-floppy-disk mr-2"></i>Save All</button></div></div></div></div></div>
    <div x-cloak x-show="showView" x-transition.opacity class="fixed inset-0 z-[60] flex items-center justify-center bg-slate-950/60 p-4"><div @click.outside="showView=false" class="w-full max-w-4xl overflow-hidden rounded-xl bg-white shadow-xl"><div class="flex items-center justify-between border-b border-slate-200 p-5"><div><h3 class="text-lg font-bold">Health and Nutrition Record Details</h3><p class="mt-1 text-sm text-slate-500">Full record details</p></div><button @click="showView=false" type="button" class="rounded-lg p-2 hover:bg-slate-100"><i class="fa-solid fa-xmark"></i></button></div><div class="grid grid-cols-1 gap-3 p-5 sm:grid-cols-2 lg:grid-cols-3"><template x-for="f in fieldMeta" :key="f.key"><div class="rounded-lg border border-slate-200 p-3"><p class="text-xs text-slate-500" x-text="f.label"></p><p class="mt-1 break-words font-semibold text-slate-800" x-text="selected && selected[f.key] ? selected[f.key] : '-' "></p></div></template></div><div class="flex justify-end border-t border-slate-200 p-4"><button @click="showView=false" type="button" class="rounded-lg bg-[#0b1f3a] px-5 py-2.5 text-sm font-semibold text-white hover:bg-[#122b4d]">Close</button></div></div></div>
