@push('scripts')
<script>
function healthNutritionPage() {
 return {
  storageKey:"cbed_health_nutrition_records",records:[],databaseRecords:[],search:'',filterProvince:'',filterGroup:'',showBulk:false,showView:false,bulkRows:[],selected:null,notice:'',rowKey:0,page:1,perPage:10,
  fieldMeta:[{"key": "animal_id", "label": "Animal ID", "type": "text", "required": true}, {"key": "farmer", "label": "Farmer", "type": "text", "required": false}, {"key": "province", "label": "Province", "type": "province", "required": false}, {"key": "cooperative", "label": "Cooperative / Association", "type": "text", "required": false}, {"key": "monitoring_date", "label": "Monitoring Date", "type": "date", "required": true}, {"key": "health_status", "label": "Health Status", "type": "health", "required": true}, {"key": "condition", "label": "Observed Condition", "type": "text", "required": false}, {"key": "feed", "label": "Feed", "type": "text", "required": false}, {"key": "supplement", "label": "Supplement", "type": "text", "required": false}, {"key": "treatment", "label": "Treatment", "type": "text", "required": false}, {"key": "services", "label": "Services / Dosage / Remarks", "type": "text", "required": false}, {"key": "body_condition", "label": "Body Condition", "type": "body", "required": false}, {"key": "temperature", "label": "Temperature (°C)", "type": "number", "required": false}, {"key": "remarks", "label": "Remarks", "type": "text", "required": false}],fieldNames:["animal_id", "farmer", "province", "cooperative", "monitoring_date", "health_status", "condition", "feed", "supplement", "treatment", "services", "body_condition", "temperature", "remarks"],provinceOptions:["Aurora", "Bataan", "Bulacan", "Nueva Ecija", "Pampanga", "Tarlac", "Zambales"],sampleData:[{"animal_id": "CBED-AN-001", "farmer": "Juan Dela Cruz", "province": "Pampanga", "cooperative": "Sample Cooperative A", "monitoring_date": "2026-10-10", "health_status": "Healthy", "condition": "Normal appetite and activity", "feed": "Napier grass and concentrate", "supplement": "Mineral block", "treatment": "None", "body_condition": "Good", "temperature": "38.5", "remarks": "Sample record only"}, {"animal_id": "CBED-AN-002", "farmer": "Maria Reyes", "province": "Nueva Ecija", "cooperative": "Sample Cooperative B", "monitoring_date": "2026-10-12", "health_status": "Under Observation", "condition": "Reduced appetite", "feed": "Napier grass", "supplement": "Mineral mix", "treatment": "Monitoring only", "body_condition": "Fair", "temperature": "39.0", "remarks": "Recheck as needed"}, {"animal_id": "CBED-AN-003", "farmer": "Pedro Santos", "province": "Tarlac", "cooperative": "Sample Cooperative C", "monitoring_date": "2026-10-15", "health_status": "Needs Follow-up", "condition": "Follow-up examination required", "feed": "Mixed forage", "supplement": "Mineral block", "treatment": "Veterinary follow-up", "body_condition": "Fair", "temperature": "38.7", "remarks": "Sample record only"}],
  optionValues(type) { const map={"province": ["Aurora", "Bataan", "Bulacan", "Nueva Ecija", "Pampanga", "Tarlac", "Zambales"], "health": ["Healthy", "Under Observation", "Under Treatment", "Needs Follow-up"], "body": ["Poor", "Fair", "Good", "Very Good"], "session": ["Morning", "Noon", "Evening", "Daily Total"], "stage": ["Early Lactation", "Mid Lactation", "Late Lactation", "Dry"], "result": ["Passed", "For Review", "Failed"], "exit": ["Sold", "Mortality", "Culled", "Transferred", "Slaughtered", "Lost / Missing", "Donated", "Other"], "exitstatus": ["Out", "Dead", "Culled", "Lost / Missing", "Transferred"]}; return map[type]||[]; },
  async init() { try { const saved=localStorage.getItem(this.storageKey);if(saved!==null){const parsed=JSON.parse(saved);this.records=Array.isArray(parsed)?parsed:[];}else this.records=[]; } catch(e){this.records=[];this.msg('Unable to read older browser records.');} try { const response=await fetch('/admin/health-nutrition-api',{headers:{Accept:'application/json'}});if(!response.ok)throw new Error('Database records could not be loaded.');this.databaseRecords=await response.json(); } catch(e){console.warn(e);this.msg(e.message);} },
  get filteredRecords() { const q=this.search.toLowerCase().trim();return [...this.databaseRecords,...this.records].filter(r=>{const matchesSearch=!q||this.fieldNames.some(f=>String(r[f]??'').toLowerCase().includes(q))||String(r.record_category??'').toLowerCase().includes(q);return matchesSearch&&(!this.filterProvince||r.province===this.filterProvince)&&(!this.filterGroup||(this.filterGroup==='Other Services'?r.record_category==='other_services':r.record_category!=='other_services'&&String(r["health_status"])===this.filterGroup));}); },
  get summaryCards() { const list=this.filteredRecords;return [{title:"Total Records",value:list.length,description:'Based on current filters',icon:"fa-solid fa-list-check"},{title:"Healthy",value:list.filter(r=>r.health_status==='Healthy').length,description:'Based on current filters',icon:"fa-solid fa-heart-pulse"},{title:"Under Observation",value:list.filter(r=>r.health_status==='Under Observation').length,description:'Based on current filters',icon:"fa-solid fa-eye"},{title:"Needs Follow-up",value:list.filter(r=>r.health_status==='Needs Follow-up').length,description:'Based on current filters',icon:"fa-solid fa-calendar-check"}]; },
  totalPages(){return Math.max(1,Math.ceil(this.filteredRecords.length/this.perPage));},
  paginatedRecords(){const list=this.filteredRecords;if(this.page>this.totalPages())this.page=this.totalPages();return list.slice((this.page-1)*this.perPage,this.page*this.perPage);},
  options(field){return [...new Set(this.records.map(r=>String(r[field]??'').trim()).filter(Boolean))].sort((a,b)=>a.localeCompare(b,undefined,{numeric:true}));},
  distribution(field){const counts={};this.filteredRecords.forEach(r=>{const name=String(r[field]||'Not specified');counts[name]=(counts[name]||0)+1;});const max=Math.max(1,...Object.values(counts));return Object.entries(counts).map(([name,count])=>({name,count,percent:count/max*100})).sort((a,b)=>b.count-a.count||a.name.localeCompare(b.name));},
  emptyRow(){const r={_key:++this.rowKey};this.fieldNames.forEach(f=>r[f]='');return r;},
  openBulk(){this.bulkRows=[this.emptyRow()];this.showBulk=true;},addRow(){this.bulkRows.push(this.emptyRow());},removeRow(i){this.bulkRows.splice(i,1);},
  addSampleRows(){this.sampleData.forEach(s=>{const r=this.emptyRow();this.fieldNames.forEach(f=>r[f]=s[f]??'');this.bulkRows.push(r);});this.msg('Added sample rows. Review them before saving.');},
  persist(){try{localStorage.setItem(this.storageKey,JSON.stringify(this.records));return true;}catch(e){this.msg('Unable to save browser data. Check browser storage settings.');return false;}},
  saveBulk(){const valid=this.bulkRows.filter(r=>String(r.animal_id ?? '').trim() && String(r.monitoring_date ?? '').trim() && String(r.health_status ?? '').trim());if(!valid.length){this.msg('Please complete all required fields marked with *.');return;}const prepared=valid.map(r=>{const x={};this.fieldNames.forEach(f=>x[f]=r[f]??'');x.id='rec-'+Date.now()+'-'+Math.random().toString(36).slice(2,9);return x;});const previous=this.records;this.records=[...prepared,...this.records];if(this.persist()){this.showBulk=false;this.page=1;this.msg(prepared.length+' record(s) saved in this browser.');}else this.records=previous;},
  view(r){this.selected={...r};this.showView=true;},remove(id){if(!confirm('Delete this record?'))return;const prev=this.records;this.records=this.records.filter(r=>r.id!==id);if(this.persist())this.msg('Record deleted.');else this.records=prev;},
  resetFilters(){this.search='';this.filterProvince='';this.filterGroup='';this.page=1;},
  msg(m){this.notice=m;setTimeout(()=>{this.notice='';},3500);},
  exportCSV(){const esc=v=>'"'+String(v??'').replace(/"/g,'""')+'"';const lines=[this.fieldNames.map(esc).join(','),...this.filteredRecords.map(r=>this.fieldNames.map(f=>esc(r[f])).join(','))];const blob=new Blob(['\uFEFF'+lines.join('\r\n')],{type:'text/csv;charset=utf-8;'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download="cbed_health_nutrition_records.csv";document.body.appendChild(a);a.click();a.remove();URL.revokeObjectURL(url);},
  importCSV(event){const file=event.target.files&&event.target.files[0];if(!file)return;const reader=new FileReader();reader.onload=()=>{try{const lines=String(reader.result||'').replace(/^\uFEFF/,'').split(/\r?\n/).filter(x=>x.trim());if(lines.length<2){this.msg('CSV has no data rows.');return;}const parse=line=>{const out=[];let val='',quoted=false;for(let i=0;i<line.length;i++){const ch=line[i];if(ch==='"'&&quoted&&line[i+1]==='"'){val+='"';i++;}else if(ch==='"')quoted=!quoted;else if(ch===','&&!quoted){out.push(val);val='';}else val+=ch;}out.push(val);return out;};const headers=parse(lines.shift()).map(h=>h.trim().toLowerCase().replace(/[\s/-]+/g,'_'));const imported=[];lines.forEach(line=>{const vals=parse(line);const r={};this.fieldNames.forEach(f=>r[f]='');headers.forEach((h,i)=>{if(this.fieldNames.includes(h))r[h]=vals[i]??'';});if(String(r.animal_id ?? '').trim() && String(r.monitoring_date ?? '').trim() && String(r.health_status ?? '').trim() ){r.id='import-'+Date.now()+'-'+Math.random().toString(36).slice(2,9);imported.push(r);}});if(!imported.length){this.msg('No valid rows found. Check required columns in the CSV.');return;}const prev=this.records;this.records=[...imported,...this.records];if(this.persist()){this.page=1;this.msg(imported.length+' record(s) imported.');}else this.records=prev;}catch(e){this.msg('Could not read the CSV. Check its headers and format.');}finally{event.target.value='';}};reader.onerror=()=>{this.msg('Could not read this CSV file.');event.target.value='';};reader.readAsText(file);}
 };
}
